package com.governai.decision;import com.governai.organization.RiskLevel;import jakarta.persistence.*;import org.hibernate.annotations.JdbcTypeCode;import org.hibernate.type.SqlTypes;import tools.jackson.databind.JsonNode;import java.math.BigDecimal;import java.time.OffsetDateTime;import java.util.UUID;@Entity @Table(name="ai_recommendation") public class AiRecommendation{@Id @GeneratedValue(strategy=GenerationType.UUID)private UUID id;@Column(name="decision_request_id",nullable=false)private UUID decisionRequestId;@Column(nullable=false,columnDefinition="text")private String recommendation;@Column(columnDefinition="text")private String explanation;@Enumerated(EnumType.STRING)@JdbcTypeCode(SqlTypes.NAMED_ENUM)@Column(name="identified_risk_level",columnDefinition="risk_level_enum")private RiskLevel identifiedRiskLevel;@Column(name="confidence_score",precision=6,scale=5)private BigDecimal confidenceScore;@Column(name="model_provider",length=100)private String modelProvider;@Column(name="model_name",length=100)private String modelName;@Column(name="model_version",length=100)private String modelVersion;@Column(name="prompt_version",length=100)private String promptVersion;@JdbcTypeCode(SqlTypes.JSON)@Column(columnDefinition="jsonb")private JsonNode metadata;@Column(name="generated_at",nullable=false)private OffsetDateTime generatedAt;@PrePersist void create(){if(generatedAt==null)generatedAt=OffsetDateTime.now();}public UUID getId(){return id;}public UUID getDecisionRequestId(){return decisionRequestId;}public void setDecisionRequestId(UUID v){decisionRequestId=v;}public String getRecommendation(){return recommendation;}public void setRecommendation(String v){recommendation=v;}public String getExplanation(){return explanation;}public void setExplanation(String v){explanation=v;}public RiskLevel getIdentifiedRiskLevel(){return identifiedRiskLevel;}public void setIdentifiedRiskLevel(RiskLevel v){identifiedRiskLevel=v;}public BigDecimal getConfidenceScore(){return confidenceScore;}public void setConfidenceScore(BigDecimal v){confidenceScore=v;}public String getModelProvider(){return modelProvider;}public void setModelProvider(String v){modelProvider=v;}public String getModelName(){return modelName;}public void setModelName(String v){modelName=v;}public String getModelVersion(){return modelVersion;}public void setModelVersion(String v){modelVersion=v;}public String getPromptVersion(){return promptVersion;}public void setPromptVersion(String v){promptVersion=v;}public JsonNode getMetadata(){return metadata;}public void setMetadata(JsonNode v){metadata=v;}public OffsetDateTime getGeneratedAt(){return generatedAt;}}
